import random
import string

# Define the word list
word_list = [
    "python", "javascript", "kotlin", "ruby", "php",
    "css", "html", "bootstrap", "django", "flask"
]

# Generate a random word from the list
def generate_word():
    return random.choice(word_list).lower()

# Function to check if a letter is in the word
def is_valid_letter(letter):
    return letter.isalpha() and len(letter) == 1

# Function to get user input and check if it's a valid guess
def get_user_guess():
    while True:
        user_guess = input("Enter a letter to guess: ").lower()
        if is_valid_letter(user_guess):
            return user_guess
        else:
            print("Please enter a single letter.")

# Function to play the game
def play_hangman():
    word = generate_word()
    num_guesses = 6
    guessed_letters = set()
    word_guessed = "_" * len(word)

    while num_guesses > 0:
        print(f"You guessed a letter! {''.join(word_guessed)}")
        user_guess = get_user_guess()
        if user_guess in guessed_letters:
            print("You've already guessed that letter.")
        else:
            guessed_letters.add(user_guess)
            if user_guess in word:
                word_guessed = ''.join(c if c in user_guess else '_' for c in word)
            else:
                num_guesses -= 1
                print(f"Sorry, that letter is not in the word. You have {num_guesses} guesses left.")

    if "_" not in word_guessed:
        print("Congratulations, you guessed the word!")
    else:
        print("Sorry, you ran out of guesses. The word was", word)

# Play the game
play_hangman()
```

This program generates a random word from a list, checks if the user's guess is a valid letter, and updates the word_guessed string accordingly. It also keeps track of the number of guesses remaining and checks if the user has won or lost the game.
